namespace Invoicing;

/// <summary>
/// Provides the existing billing API while delegating each billing concern to a focused component.
/// </summary>
public sealed class BillingManager
{
    private readonly InvoiceIssuer _invoiceIssuer;
    private readonly TaxCalculator _taxCalculator;
    private readonly DunningService _dunningService;
    private readonly LedgerService _ledgerService;

    public BillingManager()
    {
        _invoiceIssuer = new InvoiceIssuer();
        _taxCalculator = new TaxCalculator();
        _dunningService = new DunningService();
        _ledgerService = new LedgerService();
    }

    public string CreateInvoice(Invoice invoice, Account account) =>
        _invoiceIssuer.CreateInvoice(invoice, account);

    public bool ValidateInvoice(Invoice invoice) =>
        _invoiceIssuer.ValidateInvoice(invoice);

    public int IssuedCount => _invoiceIssuer.IssuedCount;

    public decimal ComputeTax(Invoice invoice, string countryCode) =>
        _taxCalculator.ComputeTax(invoice, countryCode);

    public decimal ResolveRate(string countryCode) =>
        _taxCalculator.ResolveRate(countryCode);

    public decimal NetTotal(Invoice invoice) =>
        _taxCalculator.NetTotal(invoice);

    public string IssueReminder(Invoice invoice, Account account) =>
        _dunningService.IssueReminder(invoice, account);

    public int ReminderLevel(Invoice invoice) =>
        _dunningService.ReminderLevel(invoice);

    public void Post(Invoice invoice, decimal amount) =>
        _ledgerService.Post(invoice, amount);

    public decimal Settle(Invoice invoice, decimal payment) =>
        _ledgerService.Settle(invoice, payment);

    public decimal ApplyLateFees(Invoice invoice, Account account) =>
        _dunningService.ApplyLateFees(invoice, account);

    public string Reconcile(Account account) =>
        _ledgerService.Reconcile(account);

    public decimal Balance => _ledgerService.Balance;
}

internal sealed class InvoiceIssuer
{
    private readonly List<string> _issuedNumbers = new();
    private int _nextSequence = 1;

    public int IssuedCount => _issuedNumbers.Count;

    public string CreateInvoice(Invoice invoice, Account account)
    {
        if (string.IsNullOrWhiteSpace(account.Id))
            return "no account";
        if (invoice.Lines.Any(line => string.IsNullOrWhiteSpace(line.Description)))
            return "invalid line";
        if (string.IsNullOrEmpty(invoice.Number))
            invoice.Number = $"INV-{_nextSequence++:D6}";
        if (_issuedNumbers.Contains(invoice.Number))
            return "duplicate";
        if (invoice.Lines.Count == 0)
            return "empty";
        if (account.Kind == AccountKind.Government && string.IsNullOrEmpty(account.BillingAddress))
            return "po required";

        _issuedNumbers.Add(invoice.Number);
        return invoice.Number;
    }

    public bool ValidateInvoice(Invoice invoice)
    {
        if (string.IsNullOrEmpty(invoice.Number) || invoice.Lines.Count == 0)
            return false;

        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount < 0m)
                return false;
            if (line.VatRate < 0m || line.VatRate > 1m)
                return false;
        }

        return true;
    }
}

internal sealed class TaxCalculator
{
    private const decimal ReducedRate = 0.05m;

    private readonly Dictionary<string, decimal> _vatRates =
        new(StringComparer.OrdinalIgnoreCase)
        {
            ["GB"] = 0.20m,
            ["DE"] = 0.19m,
            ["FR"] = 0.20m,
        };

    public decimal ComputeTax(Invoice invoice, string countryCode)
    {
        decimal tax = 0m;
        var defaultRate = ResolveRate(countryCode);

        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount <= 0m)
                continue;

            if (line.VatRate > 0m)
                tax += line.NetAmount * line.VatRate;
            else if (defaultRate > 0m)
                tax += line.NetAmount * defaultRate;
        }

        return Math.Round(tax, 2);
    }

    public decimal ResolveRate(string countryCode)
    {
        if (!string.IsNullOrEmpty(countryCode) &&
            _vatRates.TryGetValue(countryCode, out var rate))
        {
            return rate;
        }

        return ReducedRate;
    }

    public decimal NetTotal(Invoice invoice)
    {
        decimal net = 0m;
        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount > 0m)
                net += line.NetAmount;
        }

        return net;
    }
}

internal sealed class DunningService
{
    private readonly Dictionary<string, int> _reminderCounts =
        new(StringComparer.Ordinal);

    public string IssueReminder(Invoice invoice, Account account)
    {
        var count = GetReminderCount(invoice.Number);
        if (count >= 3)
            return "escalate";
        if (account.Kind == AccountKind.Government)
            return "no reminder";

        _reminderCounts[invoice.Number] = count + 1;
        if (count == 0)
            return "first notice";
        if (count == 1)
            return "second notice";
        return "final notice";
    }

    public int ReminderLevel(Invoice invoice)
    {
        var count = GetReminderCount(invoice.Number);
        return count > 3 ? 3 : count;
    }

    public decimal ApplyLateFees(Invoice invoice, Account account)
    {
        if (string.IsNullOrEmpty(invoice.Number))
            return 0m;

        var level = GetReminderCount(invoice.Number);
        if (level <= 0 || account.Kind == AccountKind.Government)
            return 0m;

        decimal fee = 0m;
        foreach (var line in invoice.Lines)
        {
            if (line.NetAmount > 0m)
                fee += line.NetAmount * 0.01m * level;
        }

        var maximumFee = account.Kind == AccountKind.Business ? 100m : 50m;
        return Math.Round(Math.Min(fee, maximumFee), 2);
    }

    private int GetReminderCount(string invoiceNumber) =>
        _reminderCounts.TryGetValue(invoiceNumber, out var count) ? count : 0;
}

internal sealed class LedgerService
{
    private readonly List<string> _entries = new();
    private decimal _balance;

    public decimal Balance => _balance;

    public void Post(Invoice invoice, decimal amount)
    {
        if (amount == 0m)
            return;

        if (amount > 0m)
            _entries.Add($"DR {invoice.Number} {amount}");
        else
            _entries.Add($"CR {invoice.Number} {-amount}");

        _balance += amount;
    }

    public decimal Settle(Invoice invoice, decimal payment)
    {
        if (payment <= 0m || string.IsNullOrEmpty(invoice.Number))
            return _balance;

        _entries.Add($"PMT {invoice.Number} {payment}");
        _balance = Math.Max(0m, _balance - payment);
        return _balance;
    }

    public string Reconcile(Account account)
    {
        if (string.IsNullOrEmpty(account.Id))
            return "no account";
        if (_entries.Count == 0)
            return "no entries";

        decimal credits = 0m;
        decimal debits = 0m;
        foreach (var entry in _entries)
        {
            if (entry.StartsWith("DR", StringComparison.Ordinal))
                debits += 1m;
            else if (entry.StartsWith("CR", StringComparison.Ordinal) ||
                     entry.StartsWith("PMT", StringComparison.Ordinal))
                credits += 1m;
        }

        if (_balance > 0m && debits > credits)
            return "outstanding";
        if (_balance <= 0m)
            return "settled";
        return "partial";
    }
}
